CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS realestate_properties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),property_code text NOT NULL,name text NOT NULL,property_type text NOT NULL,address_line1 text,city text,state text,country text,postal_code text,status text NOT NULL DEFAULT 'active',owner_user_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,property_code));
CREATE TABLE IF NOT EXISTS realestate_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),property_id uuid NOT NULL REFERENCES realestate_properties(id),unit_no text NOT NULL,unit_type text,area_sqft numeric(12,2),bedrooms int,bathrooms int,status text NOT NULL DEFAULT 'available',asking_price numeric(16,2),UNIQUE(tenant_id,property_id,unit_no));
CREATE TABLE IF NOT EXISTS realestate_listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),property_id uuid REFERENCES realestate_properties(id),unit_id uuid REFERENCES realestate_units(id),listing_type text NOT NULL CHECK(listing_type IN ('sale','rent','lease')),title text NOT NULL,description text,price numeric(16,2) NOT NULL,status text NOT NULL DEFAULT 'published',agent_user_id uuid REFERENCES users(id),published_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS realestate_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,phone text,email text,source text,status text NOT NULL DEFAULT 'new',assigned_agent_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS realestate_viewings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),listing_id uuid NOT NULL REFERENCES realestate_listings(id),lead_id uuid REFERENCES realestate_leads(id),scheduled_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'scheduled',notes text,agent_user_id uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS realestate_offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),listing_id uuid NOT NULL REFERENCES realestate_listings(id),buyer_user_id uuid REFERENCES users(id),amount numeric(16,2) NOT NULL,status text NOT NULL DEFAULT 'submitted',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS realestate_leases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),unit_id uuid NOT NULL REFERENCES realestate_units(id),tenant_user_id uuid REFERENCES users(id),start_date date NOT NULL,end_date date NOT NULL,rent numeric(14,2) NOT NULL,deposit numeric(14,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS realestate_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),lease_id uuid NOT NULL REFERENCES realestate_leases(id),amount numeric(14,2) NOT NULL CHECK(amount>0),payment_date date NOT NULL DEFAULT current_date,method text NOT NULL,reference text,status text NOT NULL DEFAULT 'paid');
CREATE INDEX IF NOT EXISTS idx_re_properties_tenant ON realestate_properties(tenant_id); CREATE INDEX IF NOT EXISTS idx_re_units_tenant ON realestate_units(tenant_id,status); CREATE INDEX IF NOT EXISTS idx_re_listings_tenant ON realestate_listings(tenant_id,status); CREATE INDEX IF NOT EXISTS idx_re_leads_tenant ON realestate_leads(tenant_id,status);